const innerDiameter = 17.32, bandWidth = 6.0, bandThickness = 1.6, edgeRadius = 0.4;
const rail = 1.3, wire = 1.0, halfBay = 4.0, corner = 0.4;
const scrollWire = 1.2, scrollSink = 0.5;
const bezelLength = 10.10, bezelWidth = 8.10, saddleOutset = 0.3, saddleOverlap = 0.15;
const ri = innerDiameter / 2, ro = ri + bandThickness;
const DEG = Math.PI / 180;

function ringOf(rIn, rOut, width, round) {
  const section = rect(rOut - rIn - 2 * round, width - 2 * round, { center: true })
    .offset(round, { join: 'round' })
    .translate([(rIn + rOut) / 2, 0]);
  return revolve(section).rotate([90, 0, 0]);
}

const solidBand = ringOf(ri, ro, bandWidth, edgeRadius);

const yEdge = bandWidth / 2 - rail;
const run = Math.hypot(halfBay, 2 * yEdge);
const a = (2 * yEdge) / run, b = halfBay / run;
const inset = wire / 2 + corner;
const baseX = (inset + b * corner) / a;
const apexY = (a * halfBay - inset) / b - yEdge;
function post(s, y) {
  const deg = (s / ri) / DEG;
  return cylinder(corner, (ro - ri) + 1.2).translate([0, y, ri - 0.6]).rotate([0, deg, 0]);
}
function windowAt(s0, up) {
  const sgn = up ? 1 : -1;
  return hull(
    post(s0 + baseX, -sgn * (yEdge - corner)),
    post(s0 + 2 * halfBay - baseX, -sgn * (yEdge - corner)),
    post(s0 + halfBay, sgn * apexY));
}
const start = ri * 55 * DEG;
const right = union(windowAt(start, true), windowAt(start + halfBay, false), windowAt(start + 2 * halfBay, true));
const windows = union(right, right.mirror('yz'));
const openBand = difference(solidBand, windows).named('openwork_band');

const moonstone = cabochon({ length: 8, width: 6, height: 3.5, orientation: 'east_west', name: 'moonstone' });
const standing = bezel({ stone: moonstone, wall: 1.0 });
function lowestZ(bx) {
  if (Array.isArray(bx)) return Array.isArray(bx[0]) ? bx[0][2] : bx[2];
  if (bx.min) return Array.isArray(bx.min) ? bx.min[2] : bx.min.z;
  if ('zmin' in bx) return bx.zmin;
  if ('minZ' in bx) return bx.minZ;
  throw new Error('bounds: ' + JSON.stringify(bx));
}
const bb = standing.bounds();
console.log('bezel standing bounds: ' + JSON.stringify(bb));
console.log('bezel dims: ' + JSON.stringify(standing.dims));
const setting = standing.translate([0, 0, ro - lowestZ(bb)]);

const ax = bezelLength / 2 + saddleOutset, ay = bezelWidth / 2 + saddleOutset;
const nOval = segments(ax);
const oval = [];
for (let i = 0; i < nOval; i++) {
  const t = 2 * Math.PI * i / nOval;
  oval.push([ax * Math.cos(t), ay * Math.sin(t)]);
}
const saddleTop = ro + saddleOverlap;
const saddle = intersection(
  extrude(polygon(oval), saddleTop - ri).translate([0, 0, ri]),
  ringOf(ri + edgeRadius, ro + 3, bandWidth, edgeRadius)
).named('bezel_saddle');

const rw = ro + scrollWire / 2 - scrollSink;
function onBand(u, y) { const t = u / rw; return [rw * Math.sin(t), y, rw * Math.cos(t)]; }
const u0 = rw * 22 * DEG, uc = rw * 44 * DEG;
const r0 = 1.7, r1 = 0.9, turn = 270;
const path = [];
for (let i = 0; i < 8; i++) path.push(onBand(u0 + (uc - u0) * i / 8, r0));
const steps = Math.ceil(segments(r0) * turn / 360);
for (let i = 0; i <= steps; i++) {
  const f = i / steps, al = (90 - turn * f) * DEG, r = r0 + (r1 - r0) * f;
  path.push(onBand(uc + r * Math.cos(al), r * Math.sin(al)));
}
const scrollRight = sweep(scrollWire / 2, path).named('scroll_right');
const scrollLeft = sweep(scrollWire / 2, path.map(p => [-p[0], p[1], p[2]])).named('scroll_left');

return union(openBand, saddle, setting, scrollRight, scrollLeft);
